"""Write .streamlit/config.toml from zenith.config.THEME (one source of truth).

    python scripts/gen_streamlit_config.py
"""

from __future__ import annotations

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))

from zenith.config import THEME  # noqa: E402


def render() -> str:
    return (
        "# GENERATED by scripts/gen_streamlit_config.py from zenith.config.THEME -- edit THEME, not this.\n"
        "[theme]\n"
        'base = "dark"\n'
        f'primaryColor = "{THEME.phosphor}"\n'
        f'backgroundColor = "{THEME.bg}"\n'
        f'secondaryBackgroundColor = "{THEME.panel}"\n'
        f'textColor = "{THEME.text}"\n'
        'font = "monospace"\n'
        "\n[server]\n"
        "headless = true\n"
        "enableStaticServing = true\n"
    )


if __name__ == "__main__":
    (ROOT / ".streamlit" / "config.toml").write_text(render(), encoding="utf-8")
    print("wrote .streamlit/config.toml")
